package com.dayflow.dao;
import com.dayflow.model.Subtask; import com.dayflow.util.DBConnection; import java.sql.*; import java.util.*;
public class SubtaskDAO{
 public List<Subtask> findByTask(long uid,long tid)throws Exception{List<Subtask> a=new ArrayList<>();String q="SELECT s.SUBTASK_ID,s.TASK_ID,s.TITLE,s.STATUS FROM SUBTASKS s JOIN TASKS t ON t.TASK_ID=s.TASK_ID WHERE t.USER_ID=? AND s.TASK_ID=? ORDER BY s.SUBTASK_ID";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setLong(1,uid);p.setLong(2,tid);try(ResultSet r=p.executeQuery()){while(r.next()){Subtask s=new Subtask();s.setSubtaskId(r.getLong(1));s.setTaskId(r.getLong(2));s.setTitle(r.getString(3));s.setStatus(r.getString(4));a.add(s);}}}return a;}
 public long add(long uid,long tid,String title)throws Exception{String q="INSERT INTO SUBTASKS(TASK_ID,TITLE) SELECT ?,? FROM DUAL WHERE EXISTS(SELECT 1 FROM TASKS WHERE TASK_ID=? AND USER_ID=?)";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(q,new String[]{"SUBTASK_ID"})){p.setLong(1,tid);p.setString(2,title);p.setLong(3,tid);p.setLong(4,uid);p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){return r.next()?r.getLong(1):0;}}}
 public boolean toggle(long uid,long sid)throws Exception{String q="UPDATE SUBTASKS SET STATUS=CASE WHEN STATUS='COMPLETED' THEN 'PENDING' ELSE 'COMPLETED' END WHERE SUBTASK_ID=? AND TASK_ID IN (SELECT TASK_ID FROM TASKS WHERE USER_ID=?)";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setLong(1,sid);p.setLong(2,uid);return p.executeUpdate()==1;}}
}
